script:
frappe.ui.form.on("CRM Deal", {
  setup(frm) {
    frm.set_query("custom_plan", function () {
      return {
        filters: {
          custom_project: frm.doc.custom_project || "",
        },
      };
    });
  },
  refresh(frm) {
    if (frm.doc.status === "Won") {
      frm.set_read_only();
      frm.disable_save();
    }
    frm.set_query("custom_plan", function () {
      return {
        filters: {
          custom_project: frm.doc.custom_project || "",
        },
      };
    });
  },
  custom_project(frm) {
    frm.set_value("custom_plan", "");
  }
});

frappe.ui.form.on("CRM Lead", {
  setup(frm) {
    frm.set_query("custom_plan", function () {
      return {
        filters: {
          custom_project: frm.doc.custom_project || "",
        },
      };
    });
  },
  refresh(frm) {
    frm.set_query("custom_plan", function () {
      return {
        filters: {
          custom_project: frm.doc.custom_project || "",
        },
      };
    });
  },
  custom_project(frm) {
    frm.set_value("custom_plan", "");
  }
});

frappe.ui.form.on("Customer", {
  setup(frm) {
    frm.set_query("custom_plan", function () {
      return {
        filters: {
          custom_project: frm.doc.custom_project || "",
        },
      };
    });
  },
  refresh(frm) {
    frm.set_query("custom_plan", function () {
      return {
        filters: {
          custom_project: frm.doc.custom_project || "",
        },
      };
    });
  },
  custom_project(frm) {
    frm.set_value("custom_plan", "");
  }
});

frappe.ui.form.on('Subscription Plan', {
	refresh(frm) {
        frm.set_query("add_on", "custom_addons", function(doc, cdt, cdn) {
            return {
                filters: {
                    custom_project: doc.custom_project,
                    custom_active: 1,
                    custom_subscription_type: "Addons"
                }
            };
        });
    }
})

frappe.ui.form.on('CRM Lead', {
	refresh(frm) {
        frm.set_query("add_on", "custom_addons_table", function(doc, cdt, cdn) {
            return {
                filters: {
                    custom_project: doc.custom_project,
                    custom_active: 1,
                    custom_subscription_type: "Addons"
                }
            };
        });
    }
})

frappe.ui.form.on("CRM Deal", {
    custom_sale_price: function(frm) {
        calculate_custom_amount(frm);
    },
    custom_plan: function(frm) {
        if (frm.doc.custom_plan) {
            frappe.db.get_value("Subscription Plan", frm.doc.custom_plan, "cost", function(r) {
                if (r && r.cost !== undefined) {
                    frm.set_value("custom_original_price", r.cost);
                }
            });
        }
    }
});

frappe.ui.form.on("Subscription Plan Add Ons", {
    amount: function(frm, cdt, cdn) {
        calculate_custom_amount(frm);
    },
    custom_addons_table_remove: function(frm, cdt, cdn) {
        calculate_custom_amount(frm);
    }
});

function calculate_custom_amount(frm) {
    let total = flt(frm.doc.custom_sale_price);

    if (frm.doc.custom_addons_table) {
        $.each(frm.doc.custom_addons_table, function(i, row) {
            total += flt(row.amount);
        });
    }

    frm.set_value("custom_amount", total);
}

frappe.ui.form.on("User", {
	refresh(frm) {
		if (frm.is_new()) return;

		const has_profile_cs = has_crm_lead_profile(frm.doc);

		frappe.call({
			method: "xpertintegration.api.integration.check_user_sales_and_referral",
			args: { user: frm.doc.name },
			callback: function (r) {
				if (!r.message) return;

				const { has_sales_person, has_referral_code, is_crm_lead_profile } = r.message;

				if (!has_profile_cs && !is_crm_lead_profile) return;

				if (!has_sales_person) {
					frm.add_custom_button(__("Set Commission Rate"), function () {
						frappe.prompt(
							[
								{
									label: __("Commission Rate"),
									fieldname: "commission_rate",
									fieldtype: "Data",
									reqd: 1,
									description: __("Enter the commission rate for this sales person.")
								}
							],
							function (values) {
								frappe.call({
									method: "xpertintegration.api.integration.create_sales_person",
									args: {
										user: frm.doc.name,
										commission_rate: values.commission_rate
									},
									freeze: true,
									freeze_message: __("Creating Sales Person..."),
									callback: function (res) {
										if (res.message) {
											frappe.msgprint({
												title: __("Success"),
												indicator: "green",
												message: __("Sales Person {0} created successfully.", [res.message])
											});
											frm.refresh();
										}
									}
								});
							},
							__("Set Commission Rate"),
							__("Save")
						);
					});
				}

				if (!has_referral_code) {
					frm.add_custom_button(__("Set Referral Code"), function () {
						frappe.prompt(
							[
								{
									label: __("Referral Code"),
									fieldname: "referral_code",
									fieldtype: "Data",
									reqd: 1,
									description: __("Enter the referral code for this user.")
								}
							],
							function (values) {
								frappe.call({
									method: "xpertintegration.api.integration.create_user_referral_code",
									args: {
										user: frm.doc.name,
										referral_code: values.referral_code
									},
									freeze: true,
									freeze_message: __("Creating User Referral Code..."),
									callback: function (res) {
										if (res.message) {
											frappe.msgprint({
												title: __("Success"),
												indicator: "green",
												message: __("User Referral Code {0} created successfully.", [res.message])
											});
											frm.refresh();
										}
									}
								});
							},
							__("Set Referral Code"),
							__("Save")
						);
					});
				}
			}
		});
	}
});

function has_crm_lead_profile(doc) {
	if (!doc) return false;
	if (doc.role_profile_name === "CRM Lead Profile") return true;
	if (doc.role_profiles && Array.isArray(doc.role_profiles)) {
		return doc.role_profiles.some(
			(row) => row.role_profile === "CRM Lead Profile" || row.role_profile_name === "CRM Lead Profile"
		);
	}
	return false;
}
